fn words_of(s: Str) -> List[Str] {
    var out: List[Str] = []
    var cur = ""
    for c in s.chars() {
        if c == " " {
            if cur != "" {
                out = out.push(cur)
                cur = ""
            }
        } else {
            cur = cur + c
        }
    }
    if cur != "" {
        out = out.push(cur)
    }
    return out
}

fn str_len(s: Str) -> Int {
    var n = 0
    for c in s.chars() {
        n = n + 1
    }
    return n
}

fn pieces_of(w: Str, width: Int) -> List[Str] {
    var out: List[Str] = []
    var cur = ""
    var n = 0
    for c in w.chars() {
        cur = cur + c
        n = n + 1
        if n == width {
            out = out.push(cur)
            cur = ""
            n = 0
        }
    }
    if n > 0 {
        out = out.push(cur)
    }
    return out
}

pub fn wrap(text: Str, width: Int) -> List[Str] {
    var lines: List[Str] = []
    var line = ""
    var linelen = 0
    for w in words_of(text) {
        for p in pieces_of(w, width) {
            let plen = str_len(p)
            if linelen == 0 {
                line = p
                linelen = plen
            } else if linelen + 1 + plen <= width {
                line = line + " " + p
                linelen = linelen + 1 + plen
            } else {
                lines = lines.push(line)
                line = p
                linelen = plen
            }
        }
    }
    if linelen > 0 {
        lines = lines.push(line)
    }
    return lines
}
